import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { CheckBox, Icon } from '@cetus/ui-kit'
import { Button, HStack, Menu, MenuButton, MenuList, Text, TextProps, VStack } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

function TypeCon({
  type,
  setType,
  filterList,
  labelText,
  itemFontSize = '14px',
  labelStyle = {}
}: {
  type: string
  setType: (val: string) => void
  filterList?: string[]
  labelText?: string
  itemFontSize?: string
  labelStyle?: TextProps
}) {
  const { isApp } = useWindowWidth()
  const list = filterList || ['Buy', 'Sell', 'Add', 'Remove']

  const [tempTypes, setTempTypes] = useState<string[]>(type ? type.split(',') : [])

  const toggleType = (item: string) => {
    setTempTypes(prev => (prev.includes(item) ? prev.filter(i => i !== item) : [...prev, item]))
  }

  useEffect(() => {
    setTempTypes(type ? type.split(',') : [])
  }, [type])

  const [isHover, setIsHover] = useState(false)

  return (
    <Menu
      isLazy
      onClose={() => {
        setTempTypes(type ? type.split(',') : [])
      }}
    >
      {({ onClose }) => (
        <>
          <MenuButton
            as={Button}
            variant="outline"
            h="36px"
            border="none"
            bg="none"
            p="0"
            height="16px"
            lineHeight="16px"
            w={{ base: '100%', lg: 'unset' }}
            _hover={{ bg: 'none' }}
            _active={{ bg: 'none' }}
            onMouseEnter={() => setIsHover(true)}
            onMouseLeave={() => setIsHover(false)}
          >
            <HStack gap="0" justify="center">
              <Text color="primary_gray" fontSize="13px" {...labelStyle}>
                {labelText || 'Type'}
              </Text>
              {/* {!isApp && ( */}
              <Icon mt="1px" xlinkHref="#icon-icon_filter" svgW="16px" svgH="16px" svgFill={isHover ? 'text_caption' : 'text_paragraph'} />
              {/* )} */}
            </HStack>
          </MenuButton>

          <MenuList
            zIndex={9999}
            p="4px"
            sx={{
              position: 'absolute',
              left: 0,
              top: '8px'
            }}
            // w="156px"
            minW="156px"
          >
            <VStack gap="4px">
              {list.map(item => (
                <HStack key={item} h="30px" justify="space-between" w="100%" p="0 12px" onClick={() => toggleType(item)} cursor="pointer">
                  <Text fontSize={itemFontSize}>{item}</Text>
                  <CheckBox checked={tempTypes.includes(item)} onClick={() => {}} />
                </HStack>
              ))}

              <HStack w="100%" justify="space-between" mt="8px" p="0">
                <Button
                  fontSize="12px"
                  h="28px"
                  lineHeight="28px"
                  borderRadius="8px"
                  variant="outline"
                  w="50%"
                  onClick={() => {
                    setTempTypes(type ? type.split(',') : [])
                    onClose()
                  }}
                >
                  Cancel
                </Button>
                <Button
                  fontSize="12px"
                  w="50%"
                  h="28px"
                  lineHeight="28px"
                  borderRadius="8px"
                  onClick={() => {
                    setType(tempTypes.join(','))
                    onClose()
                  }}
                >
                  Apply
                </Button>
              </HStack>
            </VStack>
          </MenuList>
        </>
      )}
    </Menu>
  )
}

export default TypeCon
